class RecordingLedger
  def initialize
    @balances = Hash.new(0)
    @journal = []
  end

  def deposit(id, amount)
    @balances[id] += amount                              # working behaviour
    @journal << { op: :deposit, id: id, amount: amount } # recorded interaction
  end

  def journal = @journal.dup                             # test-only accessor
end
